pragma solidity >=0.8.0;

contract IntDivOverflowWidthSweep {
    int16 public min16;
    int64 public min64;
    int128 public min128;
    int256 public min256;
    uint256 public count;

    constructor() {
        min16 = type(int16).min;
        min64 = type(int64).min;
        min128 = type(int128).min;
        min256 = type(int256).min;
    }

    function div16() public returns (int16) {
        int16 r = min16 / int16(-1);
        count++;
        return r;
    }

    function div64() public returns (int64) {
        int64 r = min64 / int64(-1);
        count++;
        return r;
    }

    function div128() public returns (int128) {
        int128 r = min128 / int128(-1);
        count++;
        return r;
    }

    function div256() public returns (int256) {
        int256 r = min256 / int256(-1);
        count++;
        return r;
    }

    function mod256() public returns (int256) {
        int256 r = min256 % int256(-1);
        count++;
        return r;
    }

    function okDiv16() public returns (int16) {
        int16 r = min16 / int16(2);
        count++;
        return r;
    }
}
